gpC(){return"\u0633\u062f\u0627\u062f \u0631\u0633\u0648\u0645 \u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0635\u0631\u0627\u0641 \u0627\u0644\u0622\u0644\u064a"},
gpD(){return"\u0633\u0646\u0642\u0648\u0645 \u0628\u0633\u062f\u0627\u062f \u0631\u0633\u0645\u064a\u0646 \u0634\u0647\u0631\u064a\u064b\u0627 \u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0635\u0631\u0627\u0641 \u0627\u0644\u0622\u0644\u064a \u062e\u0627\u0631\u062c \u0627\u0644\u0634\u0628\u0643\u0629 \u0641\u064a \u0627\u0644\u0648\u0644\u0627\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u062d\u062f\u0629 (\u0645\u0627 \u064a\u0635\u0644 \u0625\u0644\u0649 7.50 \u062f\u0648\u0644\u0627\u0631\u064b\u0627 \u0644\u0643\u0644 \u0645\u0646\u0647\u0627). \u064a\u0645\u0643\u0646\u0643 \u0623\u064a\u0636\u064b\u0627 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0623\u0643\u062b\u0631 \u0645\u0646 19000 \u062c\u0647\u0627\u0632 \u0635\u0631\u0627\u0641 \u0622\u0644\u064a \u0645\u062c\u0627\u0646\u064a \u0641\u064a \u062c\u0645\u064a\u0639 \u0623\u0646\u062d\u0627\u0621 \u0627\u0644\u0628\u0644\u0627\u062f."},
gtS(){return"\u062a\u062d\u0648\u064a\u0644\u0627\u062a \u0633\u0644\u0643\u064a\u0629 \u0645\u062c\u0627\u0646\u064a\u0629"},
gtT(){return"\u0642\u0645 \u0628\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0645\u062c\u0627\u0646\u064b\u0627 \u0625\u0644\u0649 \u0634\u0631\u0643\u0627\u062a \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0648\u0627\u0644\u0636\u0645\u0627\u0646 \u0648\u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0645\u062a\u0644\u0643\u0647\u0627 \u0641\u064a \u0645\u0624\u0633\u0633\u0627\u062a \u0623\u062e\u0631\u0649."},
gw7(){return"\u062f\u0641\u0639 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0625\u0631\u0633\u0627\u0644 \u0648\u0625\u064a\u062f\u0627\u0639 \u0627\u0644\u0634\u064a\u0643\u0627\u062a"},
gw8(){return"\u0642\u0645 \u0628\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0648\u062f\u0641\u0639 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0648\u0627\u0644\u062a\u0648\u062c\u064a\u0647\u060c \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0625\u0631\u0633\u0627\u0644 \u0634\u064a\u0643\u0627\u062a \u0645\u062c\u0627\u0646\u064a\u0629 \u0648\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0648\u062f\u0627\u0626\u0639 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0647\u0627\u062a\u0641 \u0627\u0644\u0645\u062d\u0645\u0648\u0644 \u0627\u0644\u062e\u0627\u0635 \u0628\u0646\u0627."},
gyH(){return"\u062a\u062d\u0648\u064a\u0644 \u0644\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0641\u064a \u062f\u0642\u0627\u0626\u0642"},
gyI(){return"\u0642\u0645 \u0628\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0646\u0642\u062f\u064a\u0629 \u0625\u0644\u0649 \u062d\u0633\u0627\u0628 \u0627\u0633\u062a\u062b\u0645\u0627\u0631 Coinetra \u0641\u064a \u062f\u0642\u0627\u0626\u0642\u060c \u0648\u0627\u062c\u0639\u0644 \u0623\u0645\u0648\u0627\u0644\u0643 \u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0623\u062c\u0644 \u062a\u0639\u0645\u0644 \u0628\u0634\u0643\u0644 \u0623\u0643\u062b\u0631 \u0635\u0639\u0648\u0628\u0629\u060c \u0641\u064a \u0623\u0633\u0631\u0639 \u0648\u0642\u062a \u0645\u0645\u0643\u0646."},
gpE(){return"\u0627\u0644\u0627\u062f\u062e\u0627\u0631 \u0648\u0627\u0644\u062a\u062d\u0648\u064a\u0644\u0627\u062a \u0627\u0644\u0622\u0644\u064a\u0629"},
gpF(){return"\u0642\u0645 \u0628\u0625\u0646\u0634\u0627\u0621 \u062e\u0637\u0637\u0643 \u0627\u0644\u0622\u0644\u064a\u0629 \u0627\u0644\u062e\u0627\u0635\u0629 \u0648\u0642\u0645 \u0628\u062a\u0639\u064a\u064a\u0646 \u0627\u0644\u062a\u062d\u0648\u064a\u0644\u0627\u062a \u0627\u0644\u0645\u062a\u0643\u0631\u0631\u0629 \u0644\u0646\u0642\u0644 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0625\u0644\u0649 \u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0627\u062f\u062e\u0627\u0631 \u0648\u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0643 \u0645\u0639 Coinetra."},
