gr7(){return"\u0639\u0628\u0631 \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u062c\u063a\u0631\u0627\u0641\u064a\u0629\u060c \u0648\u0645\u062f\u064a\u0631\u064a \u0627\u0644\u0635\u0646\u0627\u062f\u064a\u0642\u060c \u0648\u0627\u0644\u0623\u0635\u0646\u0627\u0641\u060c \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631."},
gxK(){return"\u0627\u062d\u062a\u0645\u0627\u0644\u064a\u0629 \u062e\u0641\u0636 \u0627\u0644\u0646\u0641\u0642\u0627\u062a \u0627\u0644\u0646\u0642\u062f\u064a\u0629"},
gxL(){return"\u0645\u0646 \u0627\u0644\u0645\u062d\u062a\u0645\u0644 \u0623\u0646 \u062a\u0624\u062f\u064a \u0627\u0644\u062a\u0648\u0632\u064a\u0639\u0627\u062a \u0627\u0644\u0645\u0628\u0643\u0631\u0629 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0625\u0644\u0649 \u062a\u0639\u0648\u064a\u0636 \u0645\u0643\u0627\u0644\u0645\u0627\u062a \u0631\u0623\u0633 \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u0644\u0627\u062d\u0642\u0629."},
gva(){return"\u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649 \u0627\u0644\u0623\u062f\u0646\u0649"},
gvb(){return"\u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0641\u0631\u0635 \u0635\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u0645\u062d\u0641\u0638\u0629 \u0628\u062f\u0621\u064b\u0627 \u0645\u0646 [\u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649\u060c \u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0645\u062b\u0627\u0644\u060c 50000 \u064a\u0648\u0631\u0648]\u060c \u0627\u0639\u062a\u0645\u0627\u062f\u064b\u0627 \u0639\u0644\u0649 \u0645\u0646\u0637\u0642\u062a\u0643."},
gzn(){return"\u0644\u0645\u0627\u0630\u0627 \u0635\u0646\u0627\u062f\u064a\u0642 \u0627\u0644\u0645\u062d\u0641\u0638\u0629\u061f"},
