gyq(){return"\u0938\u0940\u0930\u0940\u091c \u090f1, \u090f\u092e\u0935\u0940\u092a\u0940 \u0914\u0930 \u0935\u093e\u0923\u093f\u091c\u094d\u092f\u093f\u0915 \u0932\u0949\u0928\u094d\u091a\u0964 \u092f\u0942\u0915\u0947 \u0914\u0930 \u0938\u0940\u090f\u091a \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f\u0964"},
gyr(){return"\u090f\u091a\u0915\u0947 \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f, \u20ac28\u090f\u092e \u0938\u0940\u0930\u0940\u091c \u090f2, \u092c\u09402\u092c\u09402\u0938\u0940 \u090f\u092e\u0935\u0940\u092a\u0940\u0964"},
gys(){return"\u090f\u092b\u0906\u0930, \u092c\u0940\u0908, \u0908\u090f\u0938 \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f\u0964 B2B2C \u0938\u093e\u091d\u0947\u0926\u093e\u0930\u0940 \u0932\u093e\u0907\u0935\u0964 \u0926\u094d\u0935\u093f\u0924\u0940\u092f\u0915 \u0938\u093e\u091d\u0947\u0926\u093e\u0930\u0940."},
gyt(){return"\u20ac15m \u0938\u0940\u0930\u0940\u091c A3/B\u0964 \u0928\u093f\u0937\u094d\u0920\u093e \u0938\u093e\u091d\u0947\u0926\u093e\u0930\u0940. $125 \u092e\u093f\u0932\u093f\u092f\u0928 \u0938\u0940\u0930\u0940\u091c\u093c \u0938\u0940 (\u0907\u0928\u0938\u093e\u0907\u091f \u092a\u093e\u0930\u094d\u091f\u0928\u0930\u094d\u0938)\u0964"},
gyu(){return"\u092f\u0942\u090f\u0938\u090f, \u090f\u0938\u091c\u0940, \u090f\u092b\u0906\u0930, \u0906\u0908\u090f\u0928 \u092e\u0947\u0902 \u0932\u0949\u0928\u094d\u091a \u0915\u093f\u092f\u093e \u0917\u092f\u093e\u0964 AUM 60% \u092c\u0922\u093c\u0915\u0930 \u20ac2.3bn \u0939\u094b \u0917\u092f\u093e\u0964 \u0935\u093f\u091f\u094d\u0930\u0941\u0935\u093f\u092f\u0928 \u0928\u093f\u0935\u0947\u0936 (\u20ac35 \u092e\u093f\u0932\u093f\u092f\u0928)\u0964"},
gyv(){return"\u0928\u093f\u091c\u0940 \u0915\u093e\u0930\u094d\u092f\u093e\u0932\u092f \u0915\u093e \u0936\u0941\u092d\u093e\u0930\u0902\u092d\u0964 \u0915\u094b\u0930 \u092a\u094b\u0930\u094d\u091f\u092b\u094b\u0932\u093f\u092f\u094b II > \u20ac100m\u0964 $15m \u0938\u0940\u0930\u0940\u091c \u0938\u0940 \u090f\u0915\u094d\u0938\u091f\u0947\u0902\u0936\u0928\u0964"},
gyw(){return"ELTIF \u0932\u0949\u0928\u094d\u091a \u0915\u093f\u092f\u093e \u0917\u092f\u093e (\u20ac10k \u092e\u093f\u0928\u091f)\u0964 \u0938\u0939-\u0928\u093f\u0935\u0947\u0936 \u0914\u0930 \u0926\u094d\u0935\u093f\u0924\u0940\u092f\u0915 \u0935\u093f\u0938\u094d\u0924\u093e\u0930\u0964 \u20ac3bn \u090f\u092f\u0942\u090f\u092e \u092e\u0940\u0932 \u0915\u093e \u092a\u0924\u094d\u0925\u0930\u0964"},
gpk(){return"\u0938\u092c"},
